export const siteIcons: Record<SiteIconName, ComponentType<IconProps>> = {
  arrowClockwise: ArrowClockwise,
  arrowRight: ArrowRight,
  bank: Bank,
  buildings: Buildings,
  caretDown: CaretDown,
  certificate: Certificate,
  chartLineUp: ChartLineUp,
  equalizer: Equalizer,
  eye: Eye,
  facebookLogo: FacebookLogo,
  file: File,
  fileText: FileText,
  flagCheckered: FlagCheckered,
  flipHorizontal: FlipHorizontal,
  handshake: Handshake,
  hourglassLow: HourglassLow,
  instagramLogo: InstagramLogo,
  key: Key,
  mapPinSimpleArea: MapPinSimpleArea,
  mapTrifold: MapTrifold,
  nut: Nut,
  sealCheck: SealCheck,
  shieldCheck: ShieldCheck,
  signpost: Signpost,
  star: Star,
  target: Target,
  video: Video,
  youtubeLogo: YoutubeLogo,
}

type SiteIconProps = IconProps & {
  name: SiteIconName
}

/** Resolve a content icon key to the matching SVG component. */
export function SiteIcon({ name, className, title }: SiteIconProps) {
  const Icon = siteIcons[name]
  return <Icon className={className} title={title} />
}
